  def test_promenapodatka(self):
    self.driver.get("http://127.0.0.1:8000/")
    self.driver.set_window_size(1280, 693)
    self.driver.get("http://127.0.0.1:8000/login/")  # putanja do login strane
    self.driver.find_element(By.NAME, "email").send_keys("jovan@example.com")
    self.driver.find_element(By.NAME, "password").send_keys("lozinka123")
