    self.driver.find_element(By.NAME, "prezime").click()
    prezime_input = self.driver.find_element(By.NAME, "prezime")
    prezime_input.clear()  # briše postojeći tekst
    prezime_input.send_keys("Milvanovic")
    self.driver.find_element(By.CSS_SELECTOR, ".button:nth-child(9)").click()
    self.driver.find_element(By.CSS_SELECTOR, "#pacijent-view > div:nth-child(1)").click()
    assert self.driver.find_element(By.CSS_SELECTOR, "#pacijent-view > div:nth-child(1)").text == "Ime: Jovan Milvanovic"
  
